import { useState } from "react";
import UpgradeModal from "../components/UpgradeModal";
import { toast } from "react-hot-toast";
import "../App.css";

function GigSEO() {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [showUpgrade, setShowUpgrade] = useState(false);

  const optimize = async () => {
    try {
      if (!title.trim() || !description.trim() || !category.trim()) {
        toast.error("Please fill in title, category, and description.");
        return;
      }

      setLoading(true);

      const token = localStorage.getItem("gigora_access_token");

      const response = await fetch(
        "http://127.0.0.1:8000/api/seo/",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            title,
            description,
            category,
          }),
        }
      );

      const data = await response.json();

      // Show upgrade modal if daily limit reached
      if (response.status === 403 || response.status === 429) {
        setShowUpgrade(true);
        return;
      }

      if (!response.ok) {
        throw new Error(data.detail || "Something went wrong.");
      }

      setResult(data.data);
      toast.success("SEO optimized successfully.");
      window.dispatchEvent(new Event("dashboard-update"));
    } catch (err) {
      toast.error(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (    <div className="seo-page">
      <div className="seo-card">
        <h1>Gig SEO Optimizer</h1>

        <p>
          Optimize your Fiverr or Upwork gig with
          AI-powered SEO suggestions.
        </p>

        <div className="form-group">
          <label>Gig Title</label>

          <input
            type="text"
            placeholder="Enter your gig title..."
            value={title}
            onChange={(e) =>
              setTitle(e.target.value)
            }
          />

          <small>{title.length}/80</small>
        </div>

        <div className="form-group">
          <label>Category</label>

          <input
            type="text"
            placeholder="Enter category..."
            value={category}
            onChange={(e) =>
              setCategory(e.target.value)
            }
          />
        </div>

        <div className="form-group">
          <label>Gig Description</label>

          <textarea
            placeholder="Enter your gig description..."
            value={description}
            onChange={(e) =>
              setDescription(e.target.value)
            }
          />
        </div>

        <div className="button-row">
          <button onClick={optimize} disabled={loading}>
            {loading ? "Optimizing..." : "Optimize Gig"}
          </button>
          {result && (
            <button
              className="secondary-btn"
              onClick={optimize}
              disabled={loading}
            >
              {loading ? "Regenerating..." : "Regenerate"}
            </button>
          )}
        </div>

        {result && (
          <div className="result-box">
            <div className="result-header-row">
              <div>
                <h3>Overall Score</h3>
                <div className="overall-score-box">
                  {result.scores?.overall}/10
                </div>
              </div>

              <div className="result-actions-row">
                <button
                  className="secondary-btn"
                  onClick={() =>
                    navigator.clipboard.writeText(result.optimized_title) &&
                    toast.success("Optimized title copied.")
                  }
                >
                  Copy Title
                </button>
                <button
                  className="secondary-btn"
                  onClick={() => {
                    navigator.clipboard.writeText(
                      result.tags?.map((tag) => tag.text).join(", ") || ""
                    );
                    toast.success("Tags copied.");
                  }}
                >
                  Copy Tags
                </button>
                <button
                  className="secondary-btn"
                  onClick={() =>
                    navigator.clipboard.writeText(result.optimized_description) &&
                    toast.success("Optimized description copied.")
                  }
                >
                  Copy Description
                </button>
              </div>
            </div>

            <div className="result-section">
              <h3>Optimized Title</h3>
              <p>{result.optimized_title}</p>
            </div>

            <div className="result-section">
              <h3>Tags</h3>
              <div className="tag-list">
                {result.tags?.map((tag, index) => (
                  <span
                    key={index}
                    className={`tag-item ${tag.valid ? "tag-valid" : "tag-invalid"}`}
                  >
                    {tag.text}
                    {tag.valid ? " ✅" : " ❌"}
                  </span>
                ))}
              </div>
            </div>

            <div className="result-section">
              <h3>Optimized Description</h3>
              <p>{result.optimized_description}</p>
            </div>

            <div className="score-bars">
              <div className="score-bar-card">
                <div className="score-bar-label">
                  <span>Title Score</span>
                  <strong>{result.scores?.title}/10</strong>
                </div>
                <div className="score-bar-track">
                  <div
                    className="score-bar-fill"
                    style={{ width: `${(result.scores?.title || 0) * 10}%` }}
                  />
                </div>
              </div>

              <div className="score-bar-card">
                <div className="score-bar-label">
                  <span>Tags Score</span>
                  <strong>{result.scores?.tags}/10</strong>
                </div>
                <div className="score-bar-track">
                  <div
                    className="score-bar-fill"
                    style={{ width: `${(result.scores?.tags || 0) * 10}%` }}
                  />
                </div>
              </div>

              <div className="score-bar-card">
                <div className="score-bar-label">
                  <span>Description Score</span>
                  <strong>{result.scores?.description}/10</strong>
                </div>
                <div className="score-bar-track">
                  <div
                    className="score-bar-fill"
                    style={{ width: `${(result.scores?.description || 0) * 10}%` }}
                  />
                </div>
              </div>
            </div>
          </div>
        )}

        <UpgradeModal
          open={showUpgrade}
          onClose={() => setShowUpgrade(false)}
        />
      </div>
    </div>
  );
}

export default GigSEO;
